tracker = PreferenceTracker()
tracker.add_preference("user123", "color", "blue")
print(tracker.get_preference("user123", "color"))  # Output: blue
tracker.update_preference("user123", "color", "red")
print(tracker.get_preference("user123", "color"))  # Output: red
```

```python
class PreferenceTracker:
    def __init__(self):
        """Initialize a dictionary to store preferences for all users."""
        self.preferences = {}

    def add_preference(self, user_id, pref_name, pref_value):
        """Add a new preference for a user or update an existing one."""
        if user_id not in self.preferences:
            self.preferences[user_id] = {}
        self.preferences[user_id][pref_name] = pref_value

