import pytest

def test_swipe_right_same_user():
    user_profiles = {
        "user1": {
            "name": "Alice",
            "bio": "Hello, I like reading.",
            "interests": ["reading", "hiking"]
        }
    }
    assert swipe_right(user_profiles, "user1", "user1") == False

def test_swipe_right_non_existing_user():
    user_profiles = {
        "user1": {
            "name": "Alice",
            "bio": "Hello, I like reading.",
            "interests": ["reading", "hiking"]
        }
    }
    assert swipe_right(user_profiles, "user1", "user2") == False

def test_swipe_right_success():
    user_profiles = {
        "user1": {
            "name": "Alice",
            "bio": "Hello, I like reading.",
            "interests": ["reading", "hiking"]
        },
        "user2": {
            "name": "Bob",
            "bio": "I like playing games.",
            "interests": ["gaming", "coding"]
        }
    }
    assert swipe_right(user_profiles, "user1", "user2") == True
    assert "user2" in user_profiles["user1"]["interested"]

def test_swipe_right_additional():
    user_profiles = {
        "user1": {
            "name": "Alice",
            "bio": "Hello, I like reading.",
            "interests": ["reading", "hiking"]
        },
        "user2": {
            "name": "Bob",
            "bio": "I like playing games.",
            "interests": ["gaming", "coding"]
        },
        "user3": {
            "name": "Charlie",
            "bio": "I enjoy painting.",
            "interests": ["painting", "traveling"]
        }
    }
    assert swipe_right(user_profiles, "user1", "user2") == True
    assert swipe_right(user_profiles, "user1", "user3") == True
    assert "user2" in user_profiles["user1"]["interested"]
    assert "user3" in user_profiles["user1"]["interested"]

test_swipe_right_same_user()
test_swipe_right_non_existing_user()
test_swipe_right_success()
test_swipe_right_additional()

