def test_calculate_cagr_positive_values():
    result = calculate_cagr(1000, 2000, 3)
    expected = 0.2599210498948732  # Because (2000/1000) ** (1/3) - 1 = 0.259921
    assert abs(result - expected) < 1e-9

def test_calculate_cagr_same_beginning_and_ending_value():
    result = calculate_cagr(1000, 1000, 3)
    expected = 0.0  # Because (1000/1000) ** (1/3) - 1 = 0
    assert abs(result - expected) < 1e-9

def test_calculate_cagr_one_period():
    result = calculate_cagr(1000, 1500, 1)
    expected = 0.5  # Because (1500/1000) ** (1/1) - 1 = 0.5
    assert abs(result - expected) < 1e-9

def test_calculate_cagr_fractional_growth():
    result = calculate_cagr(1000, 1250, 2)
    expected = 0.118033988749895  # Because (1250/1000) ** (1/2) - 1 ≈ 0.118034
    assert abs(result - expected) < 1e-9

def test_calculate_cagr_invalid_values():
    try:
        calculate_cagr(-1000, 2000, 3)
        assert False, "Expected ValueError for negative beginning value"
    except ValueError:
        assert True

    try:
        calculate_cagr(1000, -2000, 3)
        assert False, "Expected ValueError for negative ending value"
    except ValueError:
        assert True

    try:
        calculate_cagr(1000, 2000, -3)
        assert False, "Expected ValueError for negative periods"
    except ValueError:
        assert True

    try:
        calculate_cagr(0, 2000, 3)
        assert False, "Expected ValueError for zero beginning value"
    except ValueError:
        assert True

    try:
        calculate_cagr(1000, 0, 3)
        assert False, "Expected ValueError for zero ending value"
    except ValueError:
        assert True

    try:
        calculate_cagr(1000, 2000, 0)
        assert False, "Expected ValueError for zero periods"
    except ValueError:
        assert True

