def test_schedule_coffee_breaks_with_conflict():
    employee_preferences = {
        "Alice": ["10:00-10:30", "11:00-11:30"],
        "Bob": ["10:00-10:30", "11:00-11:30"],
        "Charlie": ["11:00-11:30"]
    }
    result = schedule_coffee_breaks(employee_preferences)
    # Check that no overlapping slots are assigned
    assert result["Alice"] == "10:00-10:30" or result["Alice"] == "11:00-11:30"
    assert result["Bob"] == "10:00-10:30" or result["Bob"] == "11:00-11:30"
    assert result["Charlie"] == "Not Possible"
    assert result["Alice"] != result["Bob"]

