        "Charlie": ["11:00-11:30"],
        "David": ["10:30-11:00"]
    }
    result = schedule_coffee_breaks(employee_preferences)
    assigned_slots = list(result.values())
    expected_slots = ["10:00-10:30", "11:00-11:30", "10:30-11:00", "Not Possible"]
    assert sorted(assigned_slots) == ["10:00-10:30", "10:30-11:00", "11:00-11:30", "Not Possible"]

