class TicTacToe:
    def __init__(self):
        self.board = [MASK]
        self.current_player = 'X'

    def print_board(self):
        for row in self.board:
            print("|".join(row))
            print("-" * 5)

    def make_move(self, row, col):
        if self.board[row][col] == ' ':
            self.board[row][col] = self.current_player
            if self.check_winner(row, col):
                return f"Player {self.current_player} wins!"
            elif self.check_draw():
[MASK]
    def check_winner(self, row, col):
        # Check the row
        if all([cell == self.current_player for cell in self.board[row]]):
            return True
        # Check the column
        if all([self.board[r][col] == self.current_player for r in range(3)]):
            return True
        # Check diagonals
        if row == col and all([self.board[i][i] == self.current_player for i in range(3)]):
            return True
        if row + col == 2 and all([self.board[i][2 - i] == self.current_player for i in range(3)]):
            return True
        return False

    def check_draw(self):
        return all([cell != ' ' for row in self.board for cell in row])
